def audit_missing_values(df, dataset_name):
    missing_count = df.isna().sum()
    missing_pct = (missing_count / len(df) * 100).round(2)

    report = pd.DataFrame({
        "dataset": dataset_name,
        "column": df.columns,
        "missing_count": missing_count.values,
        "missing_percent": missing_pct.values
    })

    return report


