    missing_reports,
    ignore_index=True
)

missing_summary = missing_report[
    missing_report["missing_count"] > 0
].sort_values(
    ["dataset", "missing_percent"],
    ascending=[True, False]
)

if missing_summary.empty:
    print("No missing values detected.")
else:
